import importlib
import sys
from pathlib import Path

try:
    from string.templatelib import Template as TString, convert as tstring_convert
except ImportError:
    TString = None

from otree.templating.nodes import localize


def _render_chunk(chunk):
    if TString is None or not isinstance(chunk, TString):
        return str(chunk)
    parts = []
    for item in chunk:
        if isinstance(item, str):
            parts.append(item)
        elif item.conversion:
            parts.append(str(tstring_convert(item.value, item.conversion)))
        elif item.format_spec:
            parts.append(format(item.value, item.format_spec))
        else:
            parts.append(localize(item.value))
    return ''.join(parts)


_module_mtimes = {}  # module_name -> mtime


def get_pypage_path(app_name, page_name):
    path = Path(app_name, f'{page_name}_html.py')
    if path.exists():
        return path
    return None


def _load_module(app_name, page_name):
    path = get_pypage_path(app_name, page_name)
    stem = path.stem
    module_name = f'{app_name}.{stem}'
    mtime = path.stat().st_mtime
    if _module_mtimes.get(module_name) != mtime:
        if module_name in sys.modules:
            importlib.reload(sys.modules[module_name])
        else:
            importlib.import_module(module_name)
        _module_mtimes[module_name] = mtime
    return sys.modules[module_name]


_PUBLIC_CONTEXT_KEYS = ('timer_text', 'title_text', 'body_text')


class PageComponents:
    def __init__(self, context, app_name):
        self.context = context
        self._app_name = app_name
        self.form = context.get('form')

    def form_field(self, name, label=None):
        return self.formfield(name, label)

    def formfield(self, name, label=None):
        import wtforms.fields as wtfields
        from otree.templating.nodes import _render_formfield

        form = self.context['form']
        if isinstance(name, str):
            fld = form[name]
        elif isinstance(name, wtfields.Field):
            fld = name
        else:
            raise TypeError('formfield argument should be a string field name')
        if label is None:
            label = fld.label.text
        return _render_formfield(fld, label)

    def form_fields(self):
        return self.formfields()

    def formfields(self):
        form = self.context['form']
        return ''.join(self.formfield(f.name) for f in form)

    def next_button(self, label=None):
        from otree.templating.nodes import NextButton

        return NextButton(None).wrender(self.context, label=label)

    def back_button(self):
        from otree.templating.nodes import BackButton

        return BackButton(None).wrender(self.context)

    def chat(self, channel=None, nickname=None):
        from otree.chat import chat_template_tag
        from otree.templating.loader import ibis_loader

        kwargs = {}
        if channel is not None:
            kwargs['channel'] = channel
        if nickname is not None:
            kwargs['nickname'] = nickname
        tag_context = chat_template_tag(self.context, **kwargs)
        return ibis_loader.load('otree/tags/chat.html').render(
            tag_context, strict_mode=True
        )

    def js_script(self, filename):
        js = Path(self._app_name, filename).read_text(encoding='utf-8')
        return f'<script>{js}</script>'


def render_pypage(app_name, page_name, player, context):
    module = _load_module(app_name, page_name)

    components = PageComponents(context, app_name)
    kwargs = dict(player=player, components=components)
    for key in _PUBLIC_CONTEXT_KEYS:
        if key in context:
            kwargs[key] = context[key]

    title_html = ''
    if hasattr(module, 'title_block'):
        title_html = ''.join(
            _render_chunk(chunk) for chunk in module.title_block(**kwargs)
        )

    meta_title = ''
    if hasattr(module, 'meta_title_block'):
        meta_title = ''.join(
            _render_chunk(chunk) for chunk in module.meta_title_block(**kwargs)
        )

    gen = module.content_block(**kwargs)
    chunks = []
    debug_dict = None
    try:
        while True:
            chunks.append(_render_chunk(next(gen)))
    except StopIteration as e:
        debug_dict = e.value
    content_html = ''.join(chunks)

    return title_html, meta_title, content_html, debug_dict
